from ollama import chat

def get_temperature(city: str) -> str:
    """Get the current temperature for a city."""
    return {"London": "15°C", "Oslo": "8°C"}.get(city, "unknown")

tools = {"get_temperature": get_temperature}
messages = [{"role": "user", "content": "Is it warmer in London or Oslo right now?"}]

for _ in range(5):                                   # bound the loop
    response = chat(model="qwen3", messages=messages, tools=list(tools.values()))
    messages.append(response.message)
    if not response.message.tool_calls:
        break                                        # final answer
    for call in response.message.tool_calls:
        fn = tools.get(call.function.name)
        result = fn(**call.function.arguments) if fn else "unknown tool"
        print("called", call.function.name, call.function.arguments, "->", result)
        messages.append({"role": "tool", "tool_name": call.function.name, "content": result})

print(response.message.content)
# called get_temperature {'city': 'London'} -> 15°C
# called get_temperature {'city': 'Oslo'} -> 8°C
# London is warmer: 15°C versus 8°C in Oslo.

# Caddyfile: HTTPS + API key check + only chat/embed endpoints, Ollama stays on localhost
llm.example.com {
    @authorized header Authorization "Bearer {env.OLLAMA_PROXY_KEY}"
    @allowed path /api/chat /api/embed /v1/chat/completions /v1/embeddings

    handle @authorized {
        handle @allowed {
            reverse_proxy 127.0.0.1:11434
        }
        respond "Forbidden endpoint" 403
    }
    respond "Unauthorized" 401
}

# Ollama itself keeps the default bind: OLLAMA_HOST=127.0.0.1:11434
# Firewall: allow 443 from your clients; never open 11434 publicly
